### 🧱 Example: Feature & Shared Modules
```typescript
// feature/user.module.ts
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { UserListComponent } from './user-list/user-list.component';
import { UserDetailComponent } from './user-detail/user-detail.component';

@NgModule({
  declarations: [UserListComponent, UserDetailComponent],
  imports: [CommonModule],
  exports: [UserListComponent]
})
export class UserModule {}
```

```typescript
// shared/shared.module.ts
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HighlightDirective } from './directives/highlight.directive';
import { CapitalizePipe } from './pipes/capitalize.pipe';

@NgModule({
  declarations: [HighlightDirective, CapitalizePipe],
  imports: [CommonModule],
  exports: [HighlightDirective, CapitalizePipe, CommonModule]
})
export class SharedModule {}
```

```typescript
// core/core.module.ts
import { NgModule, Optional, SkipSelf } from '@angular/core';
import { AuthService } from './services/auth.service';

@NgModule({
  providers: [AuthService]
})
export class CoreModule {
  constructor(@Optional() @SkipSelf() parentModule: CoreModule) {
    if (parentModule) {
      throw new Error('CoreModule is already loaded. Import it in AppModule only.');
    }
  }
}
```

### 💡 Best Practices
- Import `CoreModule` only once in `AppModule`.
- Never import `SharedModule` into `CoreModule`.
- Keep routing separate by creating a dedicated `RoutingModule` for each feature.
- Avoid circular dependencies between feature modules.
- Lazy-load feature modules where possible to improve performance.

